266	// bearerCatalogServer answers /v2/_catalog behind a Bearer challenge whose
267	// realm is its own /token path.
268	type bearerCatalogServer struct {
269		*httptest.Server
270		tokenCalls  atomic.Int32
271		tokenAuth   atomic.Value // Authorization header seen by /token
272		firstAuth   atomic.Value // Authorization header of the first catalog GET
273		pageAuths   []string
274		pageAuthsMu chan struct{}
275	}
276	
277	func newBearerCatalogServer(t *testing.T, tokenStatus int) *bearerCatalogServer {
278		t.Helper()
279		s := &bearerCatalogServer{pageAuthsMu: make(chan struct{}, 1)}
280		var first atomic.Bool
281		s.Server = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
282			if r.URL.Path == "/token" {
283				s.tokenCalls.Add(1)
284				s.tokenAuth.Store(r.Header.Get("Authorization"))
285				if tokenStatus != 200 {
286					w.WriteHeader(tokenStatus)
287					return
288				}
289				fmt.Fprint(w, `{"token":"tok123"}`)
290				return
291			}
292			auth := r.Header.Get("Authorization")
293			if first.CompareAndSwap(false, true) {
294				s.firstAuth.Store(auth)
295			}
296			s.pageAuthsMu <- struct{}{}
297			s.pageAuths = append(s.pageAuths, auth)
298			<-s.pageAuthsMu
299			if auth != "Bearer tok123" {
300				w.Header().Set("Www-Authenticate", fmt.Sprintf(`Bearer realm="%s/token",service="x",scope="registry:catalog:*"`, s.URL))
301				w.WriteHeader(401)
302				return
303			}
304			if r.URL.Query().Get("last") == "" {
305				w.Header().Set("Link", `</v2/_catalog?n=1000&last=a>; rel="next"`)
306				_, _ = fmt.Fprint(w, catalogBody("a"))
307				return
308			}
309			_, _ = fmt.Fprint(w, catalogBody("b"))
310		}))
311		t.Cleanup(s.Close)
312		return s
313	}
