315	func TestListCatalogContextBearerFlow(t *testing.T) {
316		t.Run("with credentials the token is fetched once and reused", func(t *testing.T) {
317			s := newBearerCatalogServer(t, 200)
318			names, truncated, err := ListCatalogContext(context.Background(), s.URL, "user", "pass", 10, 1000)
319			if err != nil {
320				t.Fatal(err)
321			}
322			if got := strings.Join(names, ","); got != "a,b" || truncated {
323				t.Errorf("names = %s truncated = %v, want a,b false", got, truncated)
324			}
325			if s.tokenCalls.Load() != 1 {
326				t.Errorf("realm calls = %d, want 1 (token kept across pages)", s.tokenCalls.Load())
327			}
328			wantBasic := "Basic dXNlcjpwYXNz" // user:pass
329			if a, _ := s.tokenAuth.Load().(string); a != wantBasic {
330				t.Errorf("token endpoint Authorization = %q, want %q", a, wantBasic)
331			}
332			last := s.pageAuths[len(s.pageAuths)-1]
