354					fmt.Fprint(w, `{"token":"nope"}`)
355					return
356				}
357				w.Header().Set("Www-Authenticate", `Bearer realm="http://`+r.Host+`/token",service="x"`)
358				w.WriteHeader(401)
359			}))
360			defer srv.Close()
361			_, _, err := ListCatalogContext(context.Background(), srv.URL, "user", "pass", 10, 1000)
362			var se *StatusError
363			if !errors.As(err, &se) || se.Code != 401 || se.Source != SourceRegistry {
