428	func TestListCatalogContextCancelled(t *testing.T) {
429		release := make(chan struct{})
430		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
431			if r.URL.Query().Get("last") == "" {
432				w.Header().Set("Link", `</v2/_catalog?n=1000&last=a>; rel="next"`)
433				_, _ = fmt.Fprint(w, catalogBody("a"))
434				return
435			}
436			select {
437			case <-release:
438			case <-r.Context().Done():
439			}
440		}))
441		defer srv.Close()
442		defer close(release)
443	
444		ctx, cancel := context.WithTimeout(context.Background(), 200*time.Millisecond)
445		defer cancel()
446		names, _, err := ListCatalogContext(ctx, srv.URL, "", "", 10, 1000)
447		if !errors.Is(err, context.DeadlineExceeded) {
448			t.Fatalf("err = %v, want context.DeadlineExceeded", err)
449		}
450		if names != nil {
451			t.Errorf("names = %v, want nil", names)
452		}
453	}
